head.b:skin:
:root{--bg:#090e18;--panel:#151e2c;--border:#283547;--ink:#f7f9ff;--sub:#9fadc0;--accent:#19bd9d}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 system-ui,Arial,sans-serif}a{color:inherit;text-decoration:none}a:hover{color:var(--accent)}img{max-width:100%;height:auto}input,button{font:inherit}.shell{max-width:1170px;padding:0 18px;margin:auto}.topbar{background:#101927;border-bottom:1px solid var(--border);position:sticky;top:0;z-index:5}.topinner{min-height:74px;display:flex;align-items:center;gap:25px;flex-wrap:wrap}.logo{font-weight:800;font-size:25px;letter-spacing:-1px}.logo em{font-style:normal;color:var(--accent)}.nav{display:flex;gap:20px;flex-wrap:wrap}.nav a{color:#cad6e5;font-size:14px}.search{margin-left:auto;display:flex;gap:7px}.search input{max-width:180px;background:#1f2a39;border:1px solid var(--border);padding:9px;color:white;border-radius:9px}.search button{border:0;border-radius:9px;background:var(--accent);color:#04271f;padding:9px 13px;font-weight:750;cursor:pointer}.hero{padding:62px 0;background:radial-gradient(circle at 80% 10%,#143c38,#111c2d 52%,#090e18)}.hero small{color:var(--accent);font-weight:800;text-transform:uppercase;letter-spacing:2px}.hero h1{font-size:clamp(34px,5vw,60px);letter-spacing:-2px;line-height:1.1;margin:12px 0}.hero p{max-width:700px;color:var(--sub)}.layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:30px;padding-top:32px;padding-bottom:60px}.layout h2{font-size:24px}.sidebox{padding:20px;background:var(--panel);border:1px solid var(--border);border-radius:14px}.widget ul{padding-left:20px}.widget{margin-bottom:18px}.blog-posts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.blog-posts .post-outer,.blog-posts .post-outer-container{min-width:0;background:var(--panel);border:1px solid var(--border);border-radius:14px;overflow:hidden}.blog-posts .post{padding:16px}.blog-posts .post-title{font-size:18px;line-height:1.3;margin:0 0 10px}.post-body{color:var(--sub);overflow-wrap:anywhere}.post-body img{border-radius:10px;max-width:100%}.date-outer,.post-outer{min-width:0}.post-header,.post-footer{font-size:12px;color:var(--sub)}.blog-pager{display:flex;justify-content:space-between;margin-top:24px}.blog-pager a{background:var(--panel);padding:10px 14px;border-radius:9px}.footer{border-top:1px solid var(--border);color:var(--sub);padding:28px 0;font-size:13px}.footer a{color:white}.footer-inner{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}body.item-view .blog-posts,body.static_page .blog-posts{display:block}body.item-view .blog-posts .post,body.static_page .blog-posts .post{padding:24px}body.item-view .post-body,body.static_page .post-body{font-size:17px;line-height:1.8}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid #8cdbfa;outline-offset:3px}@media(max-width:1050px){.layout{grid-template-columns:1fr}.blog-posts{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:680px){.blog-posts{grid-template-columns:repeat(2,minmax(0,1fr))}.topinner{padding:12px 0}.search{margin-left:0;width:100%}.search input{max-width:none;flex:1}}@media(max-width:420px){.blog-posts{grid-template-columns:1fr}.nav{gap:12px}}

/* Blogger default sharing controls should never expand into poster-sized icons. */
.post-share-buttons,.post-share-buttons-top,.post-share-buttons-bottom,
.share-buttons,.sharing-buttons,.post-footer .share-buttons,
.post-footer .post-share-buttons,.post-footer .sharing-buttons{display:none!important}
.post-footer,.post-header{overflow-wrap:anywhere}
.post-footer img,.post-header img{max-width:20px!important;max-height:20px!important;width:auto!important;height:auto!important}
.blog-posts .post-outer,.blog-posts .post-outer-container{align-self:start;min-width:0}
.blog-posts .post-body figure{margin:0 0 12px}
.blog-posts .post-body figure img{display:block;width:100%;max-height:360px;object-fit:cover}
.blog-posts .post-body p{margin:10px 0}
.blog-posts .post-body a{overflow-wrap:anywhere}
.blog-posts .post-title a{display:block}
.post-body .inext-media img,.post-body .inext-movie img{width:100%;max-height:420px;object-fit:contain;background:#0b1220}
body.item-view .blog-posts .post-outer,body.item-view .blog-posts .post-outer-container{max-width:100%}

/* INEXTGROUP movie / television detail card */
.inext-media{color:var(--ink);width:100%}
.inext-media__hero{display:grid;grid-template-columns:minmax(150px,220px) minmax(0,1fr);gap:28px;align-items:start;padding:18px;border:1px solid var(--border);border-radius:18px;background:linear-gradient(145deg,#1a2937,#101827)}
.inext-media__poster{margin:0;overflow:hidden;border-radius:12px;aspect-ratio:2/3;background:#0d1625}
.inext-media__poster img{display:block;width:100%;height:100%!important;max-height:none!important;object-fit:cover!important;border-radius:12px}
.inext-media__eyebrow{color:var(--accent);font-size:12px;letter-spacing:1.1px;text-transform:uppercase;font-weight:800;margin:0 0 8px!important}
.inext-media__title{font-size:clamp(24px,3.2vw,38px)!important;line-height:1.15;margin:0 0 14px!important;overflow-wrap:anywhere}
.inext-media__facts{list-style:none;margin:0 0 14px!important;padding:0!important;display:flex;flex-wrap:wrap;gap:8px}
.inext-media__facts li{display:inline-flex;align-items:center;padding:4px 10px;border-radius:20px;background:#223245;color:#dce8f3;font-size:13px}
.inext-media__rating{color:#ffe298!important;font-weight:750}
.inext-media__genres{color:#b7c8d8;font-size:14px}
.inext-media__section{padding:22px 0;border-bottom:1px solid var(--border)}
.inext-media__section h3{font-size:21px;margin:0 0 12px}
.inext-media__section p{color:#d6e1ed;line-height:1.75}
.inext-media__source{font-size:13px;color:var(--sub);line-height:1.6}
.inext-media__source a{color:var(--accent);text-decoration:underline}
@media(max-width:620px){.inext-media__hero{grid-template-columns:1fr;padding:14px;gap:16px}.inext-media__poster{max-width:230px}.inext-media__title{font-size:27px!important}}

/* Responsive discovery homepage: uses published Blogger posts, never exposes the TMDB token. */
.inext-home-sections{display:none}
.inext-home-section{margin:0 0 46px}
.inext-home-head{display:flex;align-items:end;justify-content:space-between;gap:15px;margin:0 0 18px}
.inext-home-head h2{font-size:clamp(22px,3vw,29px);margin:0;line-height:1.2}
.inext-home-head p{margin:7px 0 0;color:var(--sub);font-size:13px}
.inext-home-head a{font-size:14px;color:var(--accent);font-weight:700;white-space:nowrap}
.inext-poster-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}
.inext-card{display:flex;flex-direction:column;min-width:0;background:var(--panel);border:1px solid var(--border);border-radius:14px;overflow:hidden;transition:transform .2s ease,border-color .2s ease}
.inext-card:hover,.inext-card:focus-within{transform:translateY(-3px);border-color:#3e847d}
.inext-card__image{display:block;aspect-ratio:2/3;background:linear-gradient(155deg,#163b3f,#152035);overflow:hidden}
.inext-card__image img{display:block;width:100%;height:100%;object-fit:cover;transition:transform .2s ease}
.inext-card:hover img{transform:scale(1.025)}
.inext-card__fallback{display:flex;height:100%;padding:16px;align-items:center;justify-content:center;font-size:15px;text-align:center;color:#c7d7e5}
.inext-card__details{padding:13px}
.inext-card__label{color:var(--accent);font-size:11px;letter-spacing:.7px;text-transform:uppercase;font-weight:750}
.inext-card__title{margin:6px 0 0;font-size:15px;line-height:1.35;font-weight:750;overflow-wrap:anywhere}
.inext-card__title a{display:block}
.inext-card__meta{color:var(--sub);font-size:12px;margin:7px 0 0}
.inext-home-empty{border:1px dashed var(--border);background:#101927;color:var(--sub);border-radius:14px;padding:22px;font-size:14px}
.inext-genre-nav{display:flex;flex-wrap:wrap;gap:10px;padding:0 0 30px}
.inext-genre-nav a{border:1px solid var(--border);background:var(--panel);color:#d8e3ee;border-radius:999px;padding:8px 13px;font-size:13px}
.inext-genre-nav a:hover{color:var(--accent);border-color:var(--accent)}
body.inext-home-ready .inext-home-sections{display:block}
body.inext-home-ready .layout #main{display:none}
body.inext-home-ready .layout>section>h2{display:none}
@media(max-width:1050px){.inext-poster-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}
@media(max-width:660px){.inext-poster-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.inext-card__details{padding:11px}.inext-home-head{align-items:start}.inext-home-head h2{font-size:22px}}
@media(prefers-reduced-motion:reduce){.inext-card,.inext-card__image img{transition:none}.inext-card:hover,.inext-card:hover img{transform:none}}

/* Home discovery: categories are already above the grid, so don't display an empty sidebar. */
body.inext-home-ready .layout{grid-template-columns:minmax(0,1fr);max-width:1170px}
body.inext-home-ready .layout>aside{display:none}
.search{min-width:260px;max-width:360px;flex:1 1 280px;justify-content:flex-end}
.search input{max-width:none;min-width:0;width:100%;flex:1 1 185px}
.search button{flex:0 0 auto}
@media(max-width:680px){.search{max-width:none;min-width:0;flex:1 1 100%;justify-content:stretch}}

/* Expanded TMDB detail preview - cast and official trailer links. */
.inext-cast-list{list-style:none!important;padding:0!important;margin:12px 0 20px!important;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.inext-cast-list li{padding:12px 14px;border:1px solid var(--border);border-radius:10px;background:#172435;color:var(--ink);font-size:14px}
.inext-cast-list span{display:block;color:var(--sub);font-size:12px;margin-top:3px}
.inext-trailers{list-style:none!important;margin:12px 0!important;padding:0!important}
.inext-trailers li{margin:10px 0}
.inext-trailers a{display:inline-block;padding:10px 14px;border-radius:10px;border:1px solid #2d796f;background:#15322f;color:#73ead0;font-size:14px;font-weight:750}
.inext-trailers a:hover{border-color:var(--accent);color:#ddfff8}
@media(max-width:550px){.inext-cast-list{grid-template-columns:1fr}}

/* On-site discovery filters, limited to publicly published Blogger posts. */
.inext-catalog-tools{background:var(--panel);border:1px solid var(--border);border-radius:14px;padding:17px;margin:0 0 25px}
.inext-catalog-tools h2{margin:0 0 10px;font-size:22px}
.inext-catalog-tools p{margin:0 0 16px;font-size:13px;color:var(--sub)}
.inext-catalog-filters{display:grid;grid-template-columns:2fr repeat(3,minmax(0,1fr));gap:10px}
.inext-catalog-filters input,.inext-catalog-filters select{background:#0e1725;color:var(--ink);border:1px solid #3a4859;border-radius:9px;min-width:0;width:100%;padding:11px;font-size:14px}
.inext-catalog-tools .inext-catalog-count{color:var(--accent);font-size:13px;margin:12px 0 0}
.inext-catalog-empty{color:var(--sub);font-size:14px;margin:8px 0}
.inext-catalog-tools[hidden],.inext-catalog-empty[hidden]{display:none!important}
@media(max-width:760px){.inext-catalog-filters{grid-template-columns:1fr 1fr}.inext-catalog-filters input{grid-column:1/-1}}
@media(max-width:450px){.inext-catalog-filters{grid-template-columns:1fr}.inext-catalog-filters input{grid-column:auto}}

/* Editorial information pages and optional display-ad slots (no affiliate marketing). */
.inext-ad-slot{margin:22px 0;min-height:80px}
.inext-ad-slot:empty{display:none}
.inext-footer-pages{width:100%;border-top:1px solid var(--border);padding-top:14px}
.inext-footer-pages ul{padding:0;margin:0;list-style:none;display:flex;flex-wrap:wrap;gap:12px 20px}
.inext-footer-pages li{display:inline}
.inext-footer-pages a{font-size:13px;color:#c7d9e6}
body.static_page .post-body h2,body.static_page .post-body h3{margin-top:25px}
body.static_page .post-body p{line-height:1.8}

/* Clearer site footer and complete-site search fallback. */
.footer-inner{display:grid;grid-template-columns:minmax(0,1fr);gap:9px}
.footer-inner>div{max-width:100%;overflow-wrap:anywhere}
.footer-inner>div:nth-child(2){font-size:12px;line-height:1.7}
.inext-footer-pages{margin-top:5px}
.inext-catalog-actions{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;margin:10px 0 0}
.inext-catalog-actions a{display:inline-flex;align-items:center;gap:6px;font-size:13px;color:var(--accent);font-weight:750;text-decoration:underline;text-underline-offset:3px}
.inext-catalog-scope{font-size:12px;color:var(--sub)}
.inext-catalog-empty a{color:var(--accent);text-decoration:underline}
.inext-card__image img{aspect-ratio:2/3}
.inext-card__image:focus-visible,.inext-card__title a:focus-visible{outline:3px solid #8cdbfa;outline-offset:3px}
@media(max-width:680px){.footer-inner{gap:12px}.inext-catalog-actions{align-items:flex-start;flex-direction:column}}

/* Accessible published movie/TV detail navigation and factual metadata. */
.inext-detail-nav{display:flex;align-items:center;flex-wrap:wrap;gap:9px;font-size:13px;color:var(--sub);margin:0 0 20px}
.inext-detail-nav a{color:var(--accent);text-decoration:underline;text-underline-offset:3px}
.inext-detail-nav span[aria-hidden='true']{opacity:.65}
.inext-media__poster img{display:block;aspect-ratio:2/3}
.inext-media__source{margin-top:18px}
@media(max-width:620px){.inext-detail-nav{margin-bottom:14px}}

/* Technical quality: visible keyboard navigation, stable media and narrow-screen resilience. */
.inext-skip{position:absolute;z-index:100;top:-100px;left:14px;padding:11px 16px;background:#effffb;color:#082b25;border:2px solid #19bd9d;border-radius:8px;font-weight:800}
.inext-skip:focus{top:12px}
html{scroll-padding-top:92px}
#inext-main-content{scroll-margin-top:90px}
.inext-card__image{position:relative;min-height:0}
.inext-card__image img{background:#132334}
.inext-card__fallback{min-height:100%;aspect-ratio:2/3}
.inext-media__poster img{width:100%;height:auto;aspect-ratio:2/3}
@media(max-width:420px){.inext-home-head{flex-wrap:wrap}.inext-home-head a{white-space:normal}.inext-catalog-filters input,.inext-catalog-filters select{font-size:16px}}

/* Discover people, biographies, cast pages and verified in-site article graph. */
.inext-cast-list a,.inext-related-list a,.inext-filmography a,.inext-person-profile a{color:var(--accent);text-decoration:underline;text-underline-offset:3px}
.inext-cast-list a:hover,.inext-related-list a:hover,.inext-person-profile a:hover{text-decoration-thickness:2px}
.inext-related-list{margin:10px 0 15px!important;padding-left:22px!important;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.inext-related-list li{color:var(--ink);padding:4px 0;overflow-wrap:anywhere}
.inext-person-profile{max-width:900px;margin:auto;color:var(--ink)}
.inext-person-profile img{border-radius:15px;max-width:230px;float:left;margin:0 20px 15px 0}
.inext-person-profile h2{font-size:clamp(26px,3vw,38px);line-height:1.2}
.inext-person-profile h3{clear:both;margin-top:24px}
.inext-person-profile li{margin:7px 0}
.inext-cast-links{clear:both}
@media(max-width:600px){.inext-related-list{grid-template-columns:1fr}.inext-person-profile img{float:none;display:block;margin:10px 0 15px}}

/* INEXTGROUP premium cinematic detail page – our own design, not a TMDB clone. */
body.item-view .inext-pro-media{color:#edf5ff}
.inext-pro-banner{background:#101927 center / cover no-repeat;border:1px solid #314455;border-radius:20px;overflow:hidden;margin-bottom:16px}
.inext-pro-hero{display:grid;grid-template-columns:210px minmax(0,1fr);gap:30px;padding:30px;align-items:center;min-height:330px}
.inext-pro-cover{width:100%;aspect-ratio:2/3;border-radius:14px;overflow:hidden;background:#142234;box-shadow:0 15px 35px rgba(0,0,0,.32)}
.inext-pro-cover img{width:100%!important;height:100%!important;max-height:none!important;object-fit:cover!important;display:block;border-radius:0!important}
.inext-pro-fallback{display:grid;place-items:center;height:100%;color:#abc3d5;text-align:center;padding:12px}
.inext-pro-kicker{font-size:12px;letter-spacing:1.5px;font-weight:800;text-transform:uppercase;color:#70ead4;margin:0 0 8px}
.inext-pro-summary h2{color:#fff;font-size:clamp(28px,4vw,43px)!important;line-height:1.12;margin:0 0 10px!important}
.inext-pro-tagline{font-style:italic;color:#d7e3ee;line-height:1.6;margin:0 0 16px}
.inext-pro-pills{display:flex;gap:9px;flex-wrap:wrap;margin:12px 0}
.inext-pro-pills span{background:#22394a;border:1px solid #476273;border-radius:999px;padding:4px 11px;font-size:13px;color:#ebf5ff}
.inext-pro-rating{font-size:15px;color:#ffdc81;font-weight:750}
.inext-pro-genres{font-size:14px;color:#b8e9df}
.inext-pro-jump{display:flex;gap:8px;flex-wrap:wrap;position:sticky;top:76px;z-index:3;background:#101927;border:1px solid #273d50;border-radius:12px;padding:11px 12px;margin:16px 0 24px}
.inext-pro-jump a{padding:5px 11px;border-radius:8px;color:#e4eef6;font-size:13px;font-weight:700}
.inext-pro-jump a:hover,.inext-pro-jump a:focus-visible{background:#1c4c48;color:#aaffec}
.inext-pro-section{padding:26px 0;border-bottom:1px solid #2b3b4c;scroll-margin-top:170px}
.inext-pro-section h3{font-size:clamp(21px,2.4vw,26px);margin:0 0 16px;color:#fff}
.inext-pro-section>p{line-height:1.85;color:#d0dfeb;font-size:16px}
.inext-pro-cast-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px}
.inext-pro-person{background:#182637;border:1px solid #324455;border-radius:13px;overflow:hidden;min-width:0}
.inext-pro-person img,.inext-pro-avatar{display:block;width:100%!important;height:auto!important;aspect-ratio:2/3;object-fit:cover!important;border-radius:0!important;background:linear-gradient(150deg,#244747,#14202b)}
.inext-pro-avatar{display:grid;place-items:center;font-size:30px;color:#b5c4cf}
.inext-pro-person>div:last-child{padding:10px 11px;line-height:1.35}
.inext-pro-person-name{display:block;color:#f2f9ff;font-size:14px;font-weight:750;overflow-wrap:anywhere}
.inext-pro-person a.inext-pro-person-name{color:#7aead3;text-decoration:underline;text-underline-offset:3px}
.inext-pro-person small{display:block;color:#aebdcd;font-size:12px;margin-top:5px}
.inext-pro-info-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:0}
.inext-info-tile{min-width:0;border:1px solid #304457;background:#152335;padding:13px;border-radius:11px}
.inext-info-tile dt{font-size:11px;text-transform:uppercase;letter-spacing:.65px;color:#9aafc3;font-weight:700}
.inext-info-tile dd{margin:4px 0 0;color:#fff;font-size:14px;font-weight:650;overflow-wrap:anywhere}
.inext-pro-trailer{display:inline-block;background:#133b3a;color:#8bf8dc;border:1px solid #2a7068;border-radius:10px;padding:10px 16px;text-decoration:none}
.inext-pro-media .inext-related{scroll-margin-top:170px}
@media(max-width:900px){.inext-pro-hero{grid-template-columns:170px 1fr;padding:22px}.inext-pro-cast-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.inext-pro-info-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:600px){.inext-pro-hero{grid-template-columns:1fr;padding:18px;gap:18px}.inext-pro-cover{max-width:185px}.inext-pro-jump{position:static}.inext-pro-cast-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.inext-pro-info-grid{grid-template-columns:1fr 1fr;gap:9px}.inext-info-tile{padding:10px}.inext-pro-section{padding:20px 0}}
@media(max-width:390px){.inext-pro-info-grid{grid-template-columns:1fr}.inext-pro-person-name{font-size:13px}}

/* Media database additions: photographic gallery, cast credits and release regions. */
.inext-pro-crew-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px}
.inext-pro-crew-member{padding:12px 14px;background:#172537;border:1px solid #30475a;border-radius:12px;min-width:0}
.inext-pro-crew-member strong,.inext-pro-crew-member>a{display:block;color:#eaf7ff;font-weight:750;font-size:14px;overflow-wrap:anywhere}
.inext-pro-crew-member>a{color:#74edd5;text-decoration:underline;text-underline-offset:3px}
.inext-pro-crew-member small{display:block;color:#a9bacc;font-size:12px;margin-top:4px}
.inext-pro-gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.inext-pro-gallery figure{margin:0;background:#142234;border:1px solid #33475a;border-radius:13px;overflow:hidden}
.inext-pro-gallery img{display:block;width:100%!important;height:175px!important;object-fit:cover!important;border-radius:0!important}
.inext-pro-gallery figcaption{padding:7px 10px;color:#cbd9e8;font-size:12px}
.inext-pro-release-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}
.inext-pro-release-list>div{display:flex;flex-wrap:wrap;gap:10px;align-items:center;padding:10px 13px;border:1px solid #30475a;border-radius:10px;background:#152335;font-size:13px}
.inext-pro-release-list span{color:#c6d9e9}
.inext-pro-caption{font-size:13px!important;color:#93a8bb!important;margin:12px 0 0}
.inext-pro-simple-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;list-style:none!important;padding:0!important}
.inext-pro-simple-list li{border:1px solid #30475a;border-radius:10px;padding:11px 14px;background:#152335;color:#e3edf8;font-size:14px}
.inext-pro-simple-list small{color:#91a8be}
.inext-pro-jump{overflow-x:auto;scrollbar-width:thin}
.inext-pro-jump a{white-space:nowrap}
@media(max-width:720px){.inext-pro-crew-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.inext-pro-gallery{grid-template-columns:repeat(2,minmax(0,1fr))}.inext-pro-release-list{grid-template-columns:1fr}}
@media(max-width:440px){.inext-pro-crew-grid,.inext-pro-simple-list{grid-template-columns:1fr}.inext-pro-gallery{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.inext-pro-gallery img{height:115px!important}}

/* Override Blogger single-post global image rules for rich movie gallery/cards. */
body.item-view .blog-posts .post-body .inext-pro-cover img{width:100%!important;height:100%!important;max-height:none!important;object-fit:cover!important}
body.item-view .blog-posts .post-body .inext-pro-person img{width:100%!important;height:auto!important;aspect-ratio:2/3;max-height:none!important;object-fit:cover!important}
body.item-view .blog-posts .post-body .inext-pro-gallery img{width:100%!important;height:175px!important;max-height:175px!important;object-fit:cover!important}
body.item-view .blog-posts .post-body .inext-person-profile>img{width:230px!important;max-width:100%;height:auto!important;object-fit:cover!important}
.inext-verified{background:#102529;border:1px solid #2b5754;border-radius:15px;padding:22px;margin:14px 0}
.inext-verified a{color:#7aead3;text-decoration:underline;text-underline-offset:3px}
@media(max-width:440px){body.item-view .blog-posts .post-body .inext-pro-gallery img{height:115px!important;max-height:115px!important}}

b:if.script:
//
(function () {
  'use strict';
  function initDiscovery() {
    var host=document.getElementById('inext-discovery');
    var posts=document.querySelectorAll('#main .post');
    if (!host) return;
    var feeds={latest:[],movie:[],tv:[],trending:[]};
    var catalog=[];
    Array.prototype.forEach.call(posts,function(post){
      var titleAnchor=post.querySelector('.post-title a, h3.post-title a, h2.post-title a');
      if (!titleAnchor || !titleAnchor.getAttribute('href')) return;
      var title=(titleAnchor.textContent||'').trim();
      if (!title) return;
      var labels=Array.prototype.map.call(post.querySelectorAll('.post-labels a, a[rel="tag"]'),function(a){return (a.textContent||'').trim().toLowerCase();});
      var proType=(post.querySelector('.inext-pro-kicker')||{}).textContent||'';
      var legacyType=(post.querySelector('.inext-media__eyebrow')||{}).textContent||'';
      var isPerson=labels.indexOf('people')!==-1 || !!post.querySelector('.inext-person-profile');
      var isTv=labels.indexOf('tv shows')!==-1 || /^(?:tv series|tv show)/i.test(proType+' '+legacyType);
      var isMovie=!isPerson && (labels.indexOf('movies')!==-1 && labels.indexOf('viewing guides')===-1 ||
        /^movie(?: information| ·)/i.test(proType+' '+legacyType));
      var poster=post.querySelector('.inext-pro-cover img, .inext-media__poster img, .inext-movie img, .post-body img');
      var rating=post.querySelector('.inext-pro-rating, .inext-media__rating');
      var dateNode=post.querySelector('.inext-pro-pills, .inext-media__facts li');
      var dateText=dateNode?(dateNode.textContent||''):'';
      var record={href:titleAnchor.href,title:title,poster:poster?poster.getAttribute('src'):'',type:isTv?'TV show':isMovie?'Movie':'Article',rating:rating?(rating.textContent||'').trim():'',labels:labels,year:/\b(19|20)\d{2}\b/.test(dateText)?(dateText.match(/\b(19|20)\d{2}\b/)||[])[0]:''};
      catalog.push(record);
      feeds.latest.push(record);
      if(labels.indexOf('trending')!==-1) feeds.trending.push(record);
      if(isTv) feeds.tv.push(record);
      if(isMovie && !isTv) feeds.movie.push(record);
    });
    function linkCard(item) {
      var article=document.createElement('article');article.className='inext-card';
      var cover=document.createElement('a');cover.className='inext-card__image';cover.href=item.href;cover.setAttribute('aria-label','Open '+item.title);
      if(item.poster){
        var img=document.createElement('img');img.loading='lazy';img.decoding='async';img.width=300;img.height=450;img.referrerPolicy='no-referrer-when-downgrade';img.src=item.poster;img.alt=item.title+' poster';img.addEventListener('error',function(){img.remove();var fallback=document.createElement('span');fallback.className='inext-card__fallback';fallback.textContent=item.title;cover.appendChild(fallback);},{once:true});cover.appendChild(img);
      }else{
        var fallback=document.createElement('span');fallback.className='inext-card__fallback';fallback.textContent=item.title;cover.appendChild(fallback);
      }
      var details=document.createElement('div');details.className='inext-card__details';
      var label=document.createElement('div');label.className='inext-card__label';label.textContent=item.type;
      var h=document.createElement('h3');h.className='inext-card__title';
      var a=document.createElement('a');a.href=item.href;a.textContent=item.title;h.appendChild(a);
      details.appendChild(label);details.appendChild(h);
      if(item.rating){var meta=document.createElement('p');meta.className='inext-card__meta';meta.textContent=item.rating;details.appendChild(meta);}
      article.appendChild(cover);article.appendChild(details);return article;
    }
    function renderCatalogue() {
      var query=(document.getElementById('inext-catalog-query').value||'').toLowerCase().trim();
      var type=document.getElementById('inext-catalog-type').value;
      var genre=document.getElementById('inext-catalog-genre').value;
      var year=document.getElementById('inext-catalog-year').value;
      var hasFilter=!!query||type!=='all'||genre!=='all'||year!=='all';
      var list=catalog.filter(function(x){
        return (!query || x.title.toLowerCase().indexOf(query)!==-1) &&
          (type==='all'||(type==='movie'?x.type==='Movie':x.type==='TV show')) &&
          (genre==='all'||x.labels.indexOf(genre)!==-1) &&
          (year==='all'||x.year===year);
      });
      var section=document.getElementById('inext-catalog-results');
      var grid=document.getElementById('inext-catalog-grid');
      var empty=document.getElementById('inext-catalog-empty');
      section.hidden=!hasFilter;
      while(grid.firstChild)grid.removeChild(grid.firstChild);
      if(hasFilter)list.slice(0,100).forEach(function(x){grid.appendChild(linkCard(x));});
      empty.hidden=!hasFilter||list.length>0;
      var fullSiteUrl='/search'+(query?'?q='+encodeURIComponent(query):'');
      document.getElementById('inext-search-all').href=fullSiteUrl;
      document.getElementById('inext-search-empty').href=fullSiteUrl;
      document.getElementById('inext-catalog-count').textContent=catalog.length?
        'Showing '+catalog.length+' published guides loaded on this page'+(hasFilter?' · '+list.length+' matching locally':''):
        'No published guides are loaded on this homepage yet.';
    }
    function setupCatalogue() {
      var yearSelect=document.getElementById('inext-catalog-year');
      var genreSelect=document.getElementById('inext-catalog-genre');
      var years={},genres={},skip={'movies':1,'tv shows':1,'people':1,'viewing guides':1,'trending':1,'tmdb':1,'inext backup':1,'internal test':1};
      catalog.forEach(function(x){
        if(x.year)years[x.year]=true;
        x.labels.forEach(function(label){if(label&&!skip[label])genres[label]=true;});
      });
      Object.keys(years).sort().reverse().forEach(function(y){
        var opt=document.createElement('option');opt.value=y;opt.textContent=y;yearSelect.appendChild(opt);
      });
      Object.keys(genres).sort().forEach(function(g){
        var opt=document.createElement('option');opt.value=g;opt.textContent=g.charAt(0).toUpperCase()+g.slice(1);genreSelect.appendChild(opt);
      });
      ['inext-catalog-query','inext-catalog-type','inext-catalog-genre','inext-catalog-year'].forEach(function(id){
        var el=document.getElementById(id);
        el.addEventListener(id==='inext-catalog-query'?'input':'change',renderCatalogue);
      });
      renderCatalogue();
    }
    function fill(id,items,max){
      var node=document.getElementById(id);if(!node)return;
      items.slice(0,max).forEach(function(item){node.appendChild(linkCard(item));});
    }
    fill('inext-trending-grid',feeds.trending,8);fill('inext-latest-grid',feeds.latest,8);fill('inext-movie-grid',feeds.movie,8);fill('inext-tv-grid',feeds.tv,8);
    if(!feeds.trending.length)document.getElementById('inext-trending-section').style.display='none';
    if(feeds.latest.length)document.getElementById('inext-latest-empty').style.display='none';
    if(!feeds.movie.length)document.getElementById('inext-movie-section').style.display='none';
    if(!feeds.tv.length)document.getElementById('inext-tv-section').style.display='none';
    setupCatalogue();
    document.body.classList.add('inext-home-ready');
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initDiscovery);
  else initDiscovery();
})();
