(function(){
  'use strict';
  function initDetailEnhancements(){
    var entry=document.querySelector('#main .post-body .inext-media');
    if(!entry || entry.getAttribute('data-inext-seo-ready')==='true')return;
    var titleEl=entry.querySelector('.inext-media__title');
    var typeEl=entry.querySelector('.inext-media__eyebrow, .inext-pro-kicker');
    var overview=entry.querySelector('#inext-overview p, .inext-media__section p');
    if(!titleEl||!typeEl||!overview)return;
    var typeText=(typeEl.textContent||'').trim().toLowerCase();
    var mediaType=/^movie(?: information| · \d{4})?$/.test(typeText)?'Movie':(/^(?:tv series|tv show information)(?: · \d{4})?$/.test(typeText)?'TVSeries':null);
    if(!mediaType)return; // Never mark fictional/test or generic content as a real title.
    var name=(titleEl.textContent||'').trim();
    var description=(overview.textContent||'').trim();
    if(!name||description.length<80)return;
    var facts=entry.querySelectorAll('.inext-media__facts li, .inext-pro-pills span');
    var date='';
    Array.prototype.forEach.call(facts,function(node){
      var value=(node.textContent||'').trim();
      if(!date && /^\d{4}-\d{2}-\d{2}$/.test(value)){
        var d=new Date(value+'T00:00:00Z');
        if(!isNaN(d.getTime()) && d.toISOString().slice(0,10)===value)date=value;
      }
    });
    var image=entry.querySelector('.inext-pro-cover img, .inext-media__poster img');
    var imageUrl='';
    if(image){
      try{
        var parsed=new URL(image.currentSrc||image.src,window.location.href);
        if(parsed.protocol==='https:')imageUrl=parsed.href;
      }catch(err){}
    }
    var source=entry.querySelector('.inext-media__source a[href*="themoviedb.org"], a[href*="themoviedb.org/movie/"], a[href*="themoviedb.org/tv/"]');
    var sameAs='';
    if(source){
      try{
        var srcUrl=new URL(source.href,window.location.href);
        if(srcUrl.protocol==='https:' && (srcUrl.hostname==='www.themoviedb.org'||srcUrl.hostname==='themoviedb.org'))sameAs=srcUrl.href;
      }catch(err){}
    }
    var canonical=document.querySelector('link[rel="canonical"]');
    var pageUrl=(canonical&&canonical.href)||window.location.href.split('#')[0].split('?')[0];
    var genreEl=entry.querySelector('.inext-pro-genres, .inext-media__genres');
    var genre=[];
    if(genreEl){
      var raw=(genreEl.textContent||'').replace(/^Genres:\s*/i,'');
      genre=raw.split('·').map(function(x){return x.trim();}).filter(Boolean);
    }
    var entity={'@context':'https://schema.org','@type':mediaType,name:name,description:description,
      mainEntityOfPage:pageUrl};
    if(date)entity.datePublished=date;
    if(imageUrl)entity.image=imageUrl;
    if(genre.length)entity.genre=genre;
    if(sameAs)entity.sameAs=sameAs;
    // Use only actually visible cast, crew and runtime on this published article.
    var actorNodes=entry.querySelectorAll('.inext-pro-person');
    var actors=[];
    Array.prototype.forEach.call(actorNodes,function(node){
      var nameEl=node.querySelector('.inext-pro-person-name');
      if(!nameEl)return;
      var actorName=(nameEl.textContent||'').trim();
      if(!actorName)return;
      var obj={'@type':'Person',name:actorName};
      var internal=node.querySelector('a.inext-pro-person-name[href]');
      if(internal){
        try{var link=new URL(internal.getAttribute('href'),pageUrl);
          if(link.origin===new URL(pageUrl).origin)obj.url=link.href;
        }catch(err){}
      }
      actors.push(obj);
    });
    if(actors.length)entity.actor=actors;
    var info=entry.querySelectorAll('.inext-info-tile');
    Array.prototype.forEach.call(info,function(node){
      var dt=node.querySelector('dt'),dd=node.querySelector('dd');
      if(!dt||!dd)return;
      var label=(dt.textContent||'').trim().toLowerCase();
      var value=(dd.textContent||'').trim();
      if(!value)return;
      if(label==='director')entity.director=value.split(',').map(function(n){
        return {'@type':'Person',name:n.trim()};
      }).filter(function(n){return n.name;});
      if(label==='production countries')entity.countryOfOrigin=value.split(',').map(function(n){
        return {'@type':'Country',name:n.trim()};
      }).filter(function(n){return n.name;});
    });
    var durationText=entry.querySelector('.inext-pro-pills');
    if(durationText){
      var runtimeMatch=(durationText.textContent||'').match(/\b(\d{1,3})\s*min\b/i);
      if(runtimeMatch && Number(runtimeMatch[1])>0)entity.duration='PT'+Number(runtimeMatch[1])+'M';
    }
    // Rating is intentionally excluded: vote count and score provenance aren't reliably present in HTML.
    var script=document.createElement('script');
    script.type='application/ld+json';
    script.textContent=JSON.stringify(entity).replace(/</g,'\\u003c');
    document.head.appendChild(script);
    var nav=document.createElement('nav');
    nav.className='inext-detail-nav';nav.setAttribute('aria-label','Breadcrumb');
    var home=document.createElement('a');home.href='/';home.textContent='Home';
    var separator=document.createElement('span');separator.setAttribute('aria-hidden','true');separator.textContent='›';
    var category=document.createElement('a');
    category.href=mediaType==='Movie'?'/search/label/Movies':'/search/label/TV%20Shows';
    category.textContent=mediaType==='Movie'?'Movies':'TV Shows';
    var sep2=separator.cloneNode(true);
    var current=document.createElement('span');current.textContent=name;current.setAttribute('aria-current','page');
    nav.appendChild(home);nav.appendChild(separator);nav.appendChild(category);nav.appendChild(sep2);nav.appendChild(current);
    entry.parentNode.insertBefore(nav,entry);
    entry.setAttribute('data-inext-seo-ready','true');
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initDetailEnhancements);
  else initDetailEnhancements();
})();
